                for m in hs[:3000]:
                    cand.append(m)
            except Exception:
                pass
    except Exception:
        pass
    # baseline: enumerated cached machines
    best=None; best_acc=-1.0
    for m in cand:
        a=ev(m)
        if a>best_acc:
            best_acc=a; best=m
    # try common simple candidates
